from branding import html_logo
"""Printable rehearsal, not an invoice or payment demand."""
from html import escape

def printable(batch):
    money=lambda x:f'BSD {x/100:,.2f}'
    rows=''.join('<tr>'+''.join('<td>'+escape(str(v))+'</td>' for v in (r['number'],r['source_customer'],r['customer_name'],r['invoice_date'],r['due_date'],money(r['total_cents']),money(r['paid_cents']),money(r['credit_cents']),money(r['balance_cents'])))+'</tr>' for r in batch['rows'])
    t=batch['totals'];review=batch['review']
    return '<!doctype html><html lang="en"><meta charset="utf-8"><title>Custom U opening-balance rehearsal</title><style>body{font:13px Arial;margin:24px;color:#222}h1{color:#b72030}table{border-collapse:collapse;width:100%}td,th{padding:7px;text-align:left;border-bottom:1px solid #ccc}thead{display:table-header-group}tr{break-inside:avoid}.notice{background:#fff1cf;padding:12px}@page{size:A4 landscape;margin:12mm}</style>'+html_logo()+'<h1>CUSTOM U · Opening-balance rehearsal 110</h1><p class="notice">REHEARSAL ONLY. These are independent review copies, excluded from live invoices, payments, statements and email. This is not a tax invoice or a request for payment.</p><p>Export as of: '+escape(batch['as_of'])+' · File: '+escape(batch['source_name'])+'</p><p>'+str(t['invoice_count'])+' invoices · '+str(t['source_customer_count'])+' source customers · Invoice total '+money(t['total_cents'])+' · Historical payments '+money(t['paid_cents'])+' · Applied credits '+money(t['credit_cents'])+' · Outstanding '+money(t['balance_cents'])+'</p><p>All unpaid included: '+('confirmed' if review['all_unpaid'] else 'unconfirmed')+' · Unapplied payments / deposits / unused credits: '+escape(review['unapplied_review'].replace('_',' '))+'</p><p>Historical payment and credit amounts are cumulative ShopVox figures, not new transactions. Retain original invoices and payment records.</p><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in ('Invoice','ShopVox customer','Custom U customer','Invoice date','Due date','Original total','Historical paid','Applied credits','Outstanding'))+'</tr></thead><tbody>'+rows+'</tbody></table><p>Source SHA-256: '+escape(batch['source_sha256'])+'</p></html>'

